package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	var in struct {
		Flavors    []string `json:"flavors"`
		StartIndex int      `json:"startIndex"`
		Target     string   `json:"target"`
	}
	if err := json.Unmarshal(data, &in); err != nil {
		panic(err)
	}
	n, start := len(in.Flavors), in.StartIndex
	best := -1
	for i, f := range in.Flavors {
		if f == in.Target {
			d := min(((i-start)%n+n)%n, ((start-i)%n+n)%n)
			if best < 0 || d < best {
				best = d
			}
		}
	}
	fmt.Println(best)
}
